usage:
To use the Mnemonic Echo Bloom effect:
1.  Save the provided GLSL code as `mnemonic_echo_bloom.gdshader` in your Godot project (e.g., `res://shaders/mnemonic_echo_bloom.gdshader`).
2.  Create a new `ColorRect` node in your scene, typically as a child of your main UI or CanvasLayer, and ensure it covers the entire viewport. Set its `Anchors` to `Full Rect` and `Mouse Filter` to `Ignore`.
3.  Create a new `ShaderMaterial` resource for the `ColorRect`'s `Material` property.
4.  Assign the `mnemonic_echo_bloom.gdshader` file to the `Shader` property of this `ShaderMaterial`.
5.  Attach a new GDScript to the `ColorRect` node (e.g., `mnemonic_echo_bloom_controller.gd`) to manage the animation and dynamic parameters. Here's an example controller script:

    gdscript
    extends ColorRect

    @export_file("*.gdshader") var shader_path: String = "res://shaders/mnemonic_echo_bloom.gdshader"
    @export_group("Animation Settings")
    @export_range(0.1, 5.0, 0.1) var bloom_duration: float = 1.0
    @export_range(0.0, 1.0, 0.01) var peak_intensity: float = 1.0
    @export_range(0.0, 1.0, 0.01) var afterimage_duration_ratio: float = 0.2

    @export_group("Shader Parameters")
    @export_range(0.0, 1.0, 0.01) var max_radius: float = 0.3
    @export_range(0.0, 5.0, 0.1) var bloom_intensity: float = 1.5
    @export_range(1.0, 3.0, 0.1) var saturation_amount: float = 1.5
    @export_range(1.0, 2.0, 0.1) var contrast_amount: float = 1.2
    @export_range(0.0, 0.05, 0.001) var distortion_strength: float = 0.01
    @export var bloom_color: Color = Color(1.0, 0.8, 0.5, 1.0)

    var _shader_material: ShaderMaterial
    var _tween: Tween

    func _ready() -> void:
    	set_anchors_and_offsets_preset(PRESET_FULL_RECT)
    	mouse_filter = Control.MOUSE_FILTER_IGNORE
    	_setup_shader_material()
    	_update_shader_parameters()

    func _setup_shader_material() -> void:
    	if material is ShaderMaterial:
    		_shader_material = material as ShaderMaterial
    	else:
    		_shader_material = ShaderMaterial.new()
    		material = _shader_material

    	if not _shader_material.shader:
    		if ResourceLoader.exists(shader_path):
    			_shader_material.shader = load(shader_path)
    		else:
    			push_error("Mnemonic Echo Bloom shader not found at: ", shader_path)
    			set_process(false)
    			return

    func _update_shader_parameters() -> void:
    	if not _shader_material or not _shader_material.shader:
    		return
    	_shader_material.set_shader_parameter("max_radius", max_radius)
    	_shader_material.set_shader_parameter("bloom_intensity", bloom_intensity)
    	_shader_material.set_shader_parameter("saturation_amount", saturation_amount)
    	_shader_material.set_shader_parameter("contrast_amount", contrast_amount)
    	_shader_material.set_shader_parameter("distortion_strength", distortion_strength)
    	_shader_material.set_shader_parameter("bloom_color", bloom_color)
    	_shader_material.set_shader_parameter("progress", 0.0)
    	_shader_material.set_shader_parameter("memory_pos_uv", Vector2(0.5, 0.5))

    func _set(property: StringName, value: Variant) -> bool:
    	var handled = super._set(property, value)
    	if handled and _shader_material and _shader_material.shader:
    		if property in ["max_radius", "bloom_intensity", "saturation_amount", "contrast_amount", "distortion_strength", "bloom_color"]:
    			_shader_material.set_shader_parameter(property, value)
    	return handled

    func trigger_bloom(memory_shard_screen_position: Vector2) -> void:
    	if not _shader_material or not _shader_material.shader:
    		push_error("Shader material or shader not properly set up.")
    		return

    	var viewport_size = get_viewport_rect().size
    	var memory_pos_uv = memory_shard_screen_position / viewport_size
    	_shader_material.set_shader_parameter("memory_pos_uv", memory_pos_uv)

    	if _tween and _tween.is_running():
    		_tween.kill()

    	_tween = create_tween()
    	_tween.set_ease(Tween.EASE_OUT)
    	_tween.set_trans(Tween.TRANS_QUAD)

    	_tween.tween_property(
    		_shader_material, "shader_parameter/progress", peak_intensity, bloom_duration * 0.5
    	)

    	_tween.tween_property(
    		_shader_material, "shader_parameter/progress", 0.0, bloom_duration * (0.5 + afterimage_duration_ratio)
    	).set_delay(bloom_duration * 0.1)

    	_tween.tween_callback(func(): _tween = null)


6.  To activate the effect from another script, get a reference to your `ColorRect` node (e.g., `get_node("Path/To/MnemonicEchoBloomEffect")`) and call its `trigger_bloom(screen_position: Vector2)` method, passing the screen coordinates where the memory shard was recovered. For example: `get_node("CanvasLayer/MnemonicEchoBloomEffect").trigger_bloom(Vector2(960, 540))` for the center of a 1920x1080 screen.

This `MnemonicFissureCannon` script provides the core logic for a weapon that consumes 'MemoryShard' resources as ammunition. Each shot degrades the loaded shard, visually and functionally, until it's permanently lost.

To use this recipe, follow these steps:

1.  **Create `memory_shard.gd` (Custom Resource):**
    Create a new GDScript file named `memory_shard.gd` and paste the following code into it. This defines the custom resource that represents a memory fragment.

    gdscript
    # memory_shard.gd
    class_name MemoryShard extends Resource

    @export_category("Memory Data")
    @export var id: String = ""
    @export var memory_name: String = "Unnamed Memory"
    @export_multiline var description: String = "A fragment of a forgotten past."

    @export_category("Integrity")
    @export_range(0.0, 1.0, 0.01) var initial_integrity: float = 1.0
    @export_range(0.0, 1.0, 0.01) var current_integrity: float = 1.0:
    	set(value):
    		current_integrity = clampf(value, 0.0, initial_integrity)
    		if current_integrity <= 0.0:
    			emit_signal("depleted", id)

    @export_category("Visuals")
    @export var visual_texture: Texture2D
    @export var degradation_shader_param: String = "degradation_level" # Uniform name in shader

    signal depleted(shard_id: String)

    func _init(p_id: String = "", p_name: String = "Unnamed Memory", p_texture: Texture2D = null):
    	id = p_id
    	memory_name = p_name
    	visual_texture = p_texture
    	current_integrity = initial_integrity

    func degrade(amount: float) -> bool:
    	current_integrity -= amount
    	return not is_depleted()

    func is_depleted() -> bool:
    	return current_integrity <= 0.0

    func get_degradation_level() -> float:
    	if initial_integrity <= 0.0:
    		return 1.0 # Fully degraded if initial integrity is zero or less
    	return 1.0 - (current_integrity / initial_integrity)


2.  **Create `memory_degrade_shader.gdshader` (Custom Shader):**
    Create a new Shader file named `memory_degrade_shader.gdshader` and paste the following GLSL code. This shader will be used to visually represent the degradation of memory shards on projectiles.

    glsl
    // memory_degrade_shader.gdshader
    shader_type spatial;
    render_mode blend_mix, depth_draw_opaque, cull_back, diffuse_lambert, specular_schlick_ggx;

    uniform sampler2D texture_albedo : source_color;
    uniform float degradation_level : hint_range(0.0, 1.0) = 0.0;
    uniform vec4 degradation_color : source_color = vec4(0.1, 0.0, 0.2, 1.0);
    uniform float degradation_noise_scale = 10.0;
    uniform sampler2D noise_texture : hint_default_white; // Use a default white texture if none provided

    void fragment() {
    	vec4 albedo_tex = texture(texture_albedo, UV);

    	// Basic desaturation and color tinting
    	vec3 original_color = albedo_tex.rgb;
    	float luminance = dot(original_color, vec3(0.2126, 0.7152, 0.0722));
    	vec3 desaturated_color = mix(original_color, vec3(luminance), degradation_level * 0.5); // Half desaturation
    	vec3 tinted_color = mix(desaturated_color, degradation_color.rgb, degradation_level * 0.75); // Tint towards degradation_color

    	// Add noise-based glitch/fade effect
    	vec2 noise_uv = SCREEN_UV * degradation_noise_scale;
    	float noise_val = texture(noise_texture, noise_uv).r;

    	// Use noise to create "holes" or "fading" as degradation increases
    	float alpha_fade = 1.0 - (noise_val * degradation_level); // More degradation = more noise-based transparency

    	// Combine effects
    	ALBEDO = tinted_color;
    	ALPHA = albedo_tex.a * clamp(alpha_fade, 0.0, 1.0); // Apply alpha fade, ensuring it doesn't go below 0

    	// Optional: Emissive glow for degraded parts
    	EMISSION = degradation_color.rgb * degradation_level * 0.5; // Glow more as it degrades
    }


3.  **Create MemoryShard Resources:**
    In the Godot editor, right-click in your FileSystem dock -> New -> Resource. Select `MemoryShard` as the resource type. Save it (e.g., `res://memories/my_first_memory.tres`). Configure its `id`, `memory_name`, `initial_integrity`, and `visual_texture`. Ensure `degradation_shader_param` is set to `"degradation_level"` to match the shader uniform.

4.  **Create a Projectile Scene (`fissure_projectile.tscn`):**
    Create a new 3D scene. The root node should be a `RigidBody3D` (or `CharacterBody3D`) to handle physics and movement. Add a `MeshInstance3D` child (e.g., with a `SphereMesh`).
    On the `MeshInstance3D`, create a new `ShaderMaterial` (under `Material Override` or `Material` for a surface). Assign `memory_degrade_shader.gdshader` to this `ShaderMaterial`'s `Shader` property.
    Attach a script (e.g., `fissure_projectile.gd`) to the root node of this projectile scene. This script should have a method to receive and apply the degradation level:

    gdscript
    # fissure_projectile.gd
    extends RigidBody3D

    @export var speed: float = 20.0
    @export var lifetime: float = 3.0

    func _ready() -> void:
    	# Assuming the projectile should move forward relative to its initial orientation
    	linear_velocity = -global_transform.basis.z * speed 
    	get_tree().create_timer(lifetime).timeout.connect(queue_free)

    func set_degradation_level(level: float) -> void:
    	var mesh_instance: MeshInstance3D = $MeshInstance3D # Adjust path if your MeshInstance3D is named differently or nested
    	if mesh_instance and mesh_instance.get_surface_override_material_count() > 0:
    		var material: ShaderMaterial = mesh_instance.get_surface_override_material(0) as ShaderMaterial
    		if material:
    			material.set_shader_parameter("degradation_level", level)


5.  **Integrate `MnemonicFissureCannon` into your scene:**
    Add a `MnemonicFissureCannon` node to your player character or world scene. In the Inspector:
    *   Set `Projectile Scene` to your `fissure_projectile.tscn`.
    *   Set `Muzzle Node` to a `Node3D` child that defines the projectile's spawn point and direction.

6.  **Load and Fire:**
    In your game logic, get a reference to the `MnemonicFissureCannon` instance.
    *   Call `cannon_instance.load_shard(my_memory_shard_resource)` to load a `MemoryShard` resource as ammunition.
    *   Call `cannon_instance.fire()` to shoot. This will consume a portion of the loaded shard's integrity and spawn a projectile.

7.  **Handle Signals:**
    Connect to the `memory_lost` and `shard_degraded` signals to update your UI, game state, or trigger other effects when a memory is fully consumed or its integrity changes.

Attach this script to a CharacterBody3D node representing the hunter. Ensure the hunter node has a child NavigationAgent3D (added programmatically) and a MeshInstance3D named 'Mesh' with a ShaderMaterial applied to its first surface. The ShaderMaterial should expose 'distortion_amount' (float) and 'color_shift' (vec3) uniforms. Call the 'update_lyra_profile(profile: Dictionary)' method from Lyra's identity management system whenever her memory profile changes. The 'profile' dictionary should contain keys like 'has_precision_aim' (bool), 'has_shielding' (bool), and 'lost_memory_count' (int) to trigger adaptive behaviors and visual changes. For example, a simple shader for the 'Mesh' could be:

glsl
shader_type spatial;

uniform float distortion_amount : hint_range(0.0, 1.0) = 0.0;
uniform vec3 color_shift : hint_color = vec3(0.0);

void fragment() {
	vec2 uv = SCREEN_UV;
	uv.x += sin(uv.y * 10.0 + TIME * 5.0) * 0.01 * distortion_amount;
	uv.y += cos(uv.x * 10.0 + TIME * 5.0) * 0.01 * distortion_amount;

	vec4 base_color = texture(SCREEN_TEXTURE, uv);
	ALBEDO = base_color.rgb + color_shift;
	ALPHA = base_color.a;
}

This `MemoryShard` resource defines the core logic for memory fragments. To integrate it into your game:

1.  **Create the Shader:** Save the following GLSL code as `memory_shard_dissolve.gdshader` in your project:

    glsl
    shader_type spatial;
    render_mode blend_mix, depth_draw_opaque, cull_back;

    uniform sampler2D texture_albedo : source_color;
    uniform sampler2D texture_noise : hint_default_black; // A noise texture for varied dissolve
    uniform float dissolve_amount : hint_range(0.0, 1.0) = 0.0; // 0.0 = fully visible, 1.0 = fully dissolved
    uniform vec4 dissolve_edge_color : source_color = vec4(1.0, 0.5, 0.0, 1.0);
    uniform float dissolve_edge_width : hint_range(0.0, 0.1) = 0.02;

    void fragment() {
    	vec4 albedo_tex = texture(texture_albedo, UV);
    	vec4 noise_tex = texture(texture_noise, UV);

    	float dissolve_threshold = dissolve_amount;
    	float noise_value = noise_tex.r; // Use red channel of noise

    	// Apply dissolve effect
    	if (noise_value < dissolve_threshold) {
    		discard;
    	}

    	// Add glowing edge effect during dissolve
    	float edge_start = dissolve_threshold;
    	float edge_end = dissolve_threshold + dissolve_edge_width;

    	if (noise_value >= edge_start && noise_value < edge_end) {
    		ALBEDO = dissolve_edge_color.rgb;
    		ALPHA = dissolve_edge_color.a;
    	} else {
    		ALBEDO = albedo_tex.rgb;
    		ALPHA = albedo_tex.a;
    	}
    }


2.  **Create a Visual Node:** In your scene, create a `MeshInstance3D` (for 3D shards) or `Sprite2D` (for 2D shards) to represent a memory fragment. Let's call this `MemoryShardVisual`.

3.  **Apply Shader Material:**
    *   Create a new `ShaderMaterial` for `MemoryShardVisual`.
    *   Assign `memory_shard_dissolve.gdshader` to its `Shader` property.
    *   Assign a base `texture_albedo` (e.g., a glowing crystal texture) and a `texture_noise` (e.g., a Perlin noise texture) to the shader uniforms.

4.  **Attach a Controller Script:** Create a new GDScript (e.g., `MemoryShardController.gd`) and attach it to your `MemoryShardVisual` node. This script will manage the `MemoryShard` resource and its visual effects.

    gdscript
    # filename: MemoryShardController.gd
    extends MeshInstance3D # Or Sprite2D for 2D

    @export var memory_shard_resource: MemoryShard # Assign your MemoryShard resource here

    var current_material: ShaderMaterial

    func _ready():
    	if memory_shard_resource:
    		memory_shard_resource.shard_used.connect(_on_shard_used)
    		memory_shard_resource.shard_lost.connect(_on_shard_lost)

    	# Get the ShaderMaterial instance
    	if material_override is ShaderMaterial:
    		current_material = material_override
    	elif get_active_material(0) is ShaderMaterial:
    		current_material = get_active_material(0) as ShaderMaterial
    	else:
    		printerr("MemoryShardVisual requires a ShaderMaterial.")
    		set_process(false)

    func use_shard():
    	if memory_shard_resource and not memory_shard_resource.is_lost():
    		memory_shard_resource.use()

    func _on_shard_used(shard_type: String, current_integrity_ratio: float):
    	# Example: Trigger a subtle visual pulse or sound effect on use
    	print("Shard '" + shard_type + "' used. Integrity: " + str(current_integrity_ratio))
    	# You could tween a temporary color change or scale here

    func _on_shard_lost(shard_type: String):
    	print("Shard '" + shard_type + "' lost forever!")
    	# Animate the dissolution effect
    	if current_material:
    		var tween = create_tween()
    		tween.tween_property(current_material, "shader_parameter/dissolve_amount", 1.0, 1.5).set_ease(Tween.EASE_IN)
    		tween.tween_callback(Callable(self, "queue_free")) # Remove the node after dissolution
    	else:
    		queue_free() # Just remove if no material to dissolve


5.  **Instantiate and Use:** In your game logic (e.g., Player script), you would have a reference to `MemoryShardController` and call its `use_shard()` method when the player activates a memory fragment.
